def backfill_invoice_numbers(apps, schema_editor):
    """Give every existing invoice a gap-free number before the unique
    constraint is added, so a database with rows can be migrated safely."""
    from collections import defaultdict

    Invoice = apps.get_model("finance", "Invoice")
    counters = defaultdict(int)
    for invoice in Invoice.objects.order_by(
            "institution_id", "created", "pk").iterator():
        year = invoice.created.year if invoice.created else 0
        key = (invoice.institution_id, year)
        counters[key] += 1
        Invoice.objects.filter(pk=invoice.pk).update(
            number=f"INV-{year}-{counters[key]:06d}")


